function stationKey(name) {
 return String(name || "unbekannt")
 .toLowerCase()
 .trim()
 .replace(/[^a-z0-9]+/g, "_")
 .replace(/^_+|_+$/g, "");
}

function topicTagFromNodeId(nodeId) {
 const m = String(nodeId).match(/^ns=\d+;s=(.*)$/);
 if (!m) return String(nodeId).replace(/[^A-Za-z0-9]+/g, "_");
 const raw = m[1].replace(/^"+|"+$/g, "");
 return raw
 .replace(/[^A-Za-z0-9]+/g, "_")
 .replace(/^_+|_+$/g, "");
}

let stationName = "unbekannt";
const items = [];
const seen = new Set();

for (const rawLine of lines) {
 const line = rawLine.trim();
 if (!line) continue;

 if (line.startsWith("#")) {
 stationName = line.replace(/^#+/, "").trim() || stationName;
 continue;
 }

 const m = line.match(/^(\d+\.\d+\.\d+\.\d+:\d+)\s+(ns=\d+;[sigb]=[^\s]+)\s+([A-Za-z0-9]+)$/i);
 if (!m) continue;

 const endpoint = m[1];
 const nodeId = m[2].trim();
 const datatype = m[3].trim();
 const station = stationKey(stationName);
 const tag = topicTagFromNodeId(nodeId);

 const dedupKey = `${endpoint}|${nodeId}`;
 if (seen.has(dedupKey)) continue;
 seen.add(dedupKey);

 items.push({ endpoint, nodeId, datatype, station, tag });
}

