 endpoint: it.endpoint,
 station: it.station,
 tag: it.tag,
 datatype: it.datatype,
 nodeId: it.nodeId,
 topic: it.nodeId,
 payload: ""
}));

return [messages];

let value = msg.payload;

if (Array.isArray(value) && value.length > 0) {
 const first = value[0];
 if (first && typeof first === "object" && first.value !== undefined) {
 value = first.value;
 } else {
 value = first;
 }
} else if (value && typeof value === "object" && value.value !== undefined) {
 value = value.value;
}

