    flow.set("lastValues", lastValues);
    return msg;
} else {
    return null; // Nachricht verwerfen, keine Aenderung relevant
}

msg.payload = JSON.stringify({
 station: msg.station,
 endpoint: msg.endpoint,
 nodeId: msg.nodeId,
 tag: msg.tag,
 datatype: msg.datatype,
 wert: msg.payload,
 zeitstempel: new Date().toISOString()
});
return msg;

